import React, { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import "../style.css";
import bgImage from "../assets/img1.jpg";
import { apiRequest, saveSession } from "../api";

function Login() {
  const navigate = useNavigate();

  const [formData, setFormData] = useState({
    email: "",
    password: "",
  });
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value,
    });
  };

  const handleLogin = async (e) => {
    e.preventDefault();
    setError("");
    setLoading(true);
    try {
      const session = await apiRequest("/auth/login", {
        method: "POST",
        body: JSON.stringify(formData),
      });
      saveSession(session);
      if (session.user.role === "admin") navigate("/admin/dashboard");
      else if (session.user.role === "staff") navigate("/staff/dashboard");
      else navigate("/");
    } catch (requestError) {
      setError(requestError.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div
      className="auth-wrapper"
      style={{ backgroundImage: `url(${bgImage})` }}
    >
      <div className="auth-overlay" />

      <div className="auth-card">

        <div className="auth-header">
          <div className="brand-circle mb-2" />
          <h2>Welcome Back</h2>
          <p>Login to Villa Tjeozabel</p>
        </div>

        <form onSubmit={handleLogin}>

          {error && <p role="alert" style={{ color: "#b42318" }}>{error}</p>}

          <div className="mb-3 text-start">
            <label>Email</label>
            <input
              type="email"
              name="email"
              className="form-control auth-input"
              placeholder="Enter your email"
              value={formData.email}
              onChange={handleChange}
              required
            />
          </div>

          <div className="mb-3 text-start">
            <label>Password</label>
            <input
              type="password"
              name="password"
              className="form-control auth-input"
              placeholder="Enter your password"
              value={formData.password}
              onChange={handleChange}
              required
            />
          </div>

          <button className="btn auth-btn w-100" type="submit">
            {loading ? "Signing in..." : "Login"}
          </button>

          <p className="auth-switch mt-3">
            Don't have an account?{" "}
            <Link to="/signup">Sign Up</Link>
          </p>

          <p className="auth-back">
            <Link to="/">← Back to Home</Link>
          </p>

        </form>
      </div>
    </div>
  );
}

export default Login;
